# d-3-mod4, experiment 2.  64 points (k = 6).
# (a) the hidden symmetry: linear maps of the frequencies that keep |y| modulo 4 (generated by y -> y + (y.v) v, |v| = 2 mod 4)
#     and those that keep only the dot product; orders and orbits, k = 3..6 (exact, integers).
# (b) EXHAUSTIVE over three flags that each use only their top two levels:
#     f(y) = alpha if c.y = 1 ;  beta if c.y = 0 and d.y = 1 ;  0 otherwise   (alpha, beta in Z_4; 63 * 31 choices of (c,{d,d+c}))
#     all triples with f1 + f2 + f3 = |y| mod 4.  Prediction from the rule found at 16 points: exactly the orthonormal bases
#     of F_2^6 (for the dot product) split into pairs of equal weight mod 4:  2*15 + 30*3 = 120 triples.
import sys, itertools, time
t0 = time.time()
pc = lambda x: bin(x).count("1")
def gen_group(k, gens, cap=400000):
    n = 1 << k
    ident = tuple(1 << b for b in range(k))
    def app(A, y):
        r = 0
        for b in range(k):
            if y >> b & 1: r ^= A[b]
        return r
    def mul(A, B): return tuple(app(A, B[b]) for b in range(k))     # A after B
    seen = {ident}; front = [ident]
    while front and len(seen) < cap:
        nxt = []
        for A in front:
            for G in gens:
                C = mul(G, A)
                if C not in seen: seen.add(C); nxt.append(C)
        front = nxt
    return seen, app
for k in (3, 4, 5, 6):
    n = 1 << k
    tv = lambda v: tuple((1 << b) ^ (v if (v >> b & 1) else 0) for b in range(k))
    g2 = [tv(v) for v in range(1, n) if pc(v) % 4 == 2]
    g0 = [tv(v) for v in range(1, n) if pc(v) % 2 == 0]
    Gq, app = gen_group(k, g2); Gd, _ = gen_group(k, g0)
    okq = all(pc(app(A, y)) % 4 == pc(y) % 4 for A in list(Gq)[:200] for y in range(n))
    # orbits of Gq on vectors
    left = set(range(n)); orbs = []
    while left:
        y = min(left); o = {app(A, y) for A in Gq}; orbs.append(o); left -= o
    import math
    print("k=%d: maps keeping |y| mod 4: %d (permutations alone: %d; check %s) ; keeping the dot product: %d ; orbits on frequencies: %s"
          % (k, len(Gq), math.factorial(k), okq, len(Gd), sorted((len(o), sorted({pc(y) % 4 for y in o})) for o in orbs)))
    sys.stdout.flush()

k = 6; n = 64
M = (1 << n) - 1
def planes(vals):
    lo = hi = 0
    for y, v in enumerate(vals):
        if v & 1: lo |= 1 << y
        if v & 2: hi |= 1 << y
    return lo, hi
def add(a, b): return (a[0] ^ b[0], a[1] ^ b[1] ^ (a[0] & b[0]))
def neg(a):                         # -v mod 4 : lo same, hi ^= lo
    return (a[0], a[1] ^ a[0])
dotm = [[pc(a & y) & 1 for y in range(n)] for a in range(n)]
funcs = {}                           # key (lo,hi) -> (c, d, alpha, beta)
for c in range(1, n):
    for al in range(4):
        if al:
            f = planes([al * dotm[c][y] for y in range(n)]); funcs.setdefault(f, (c, 0, al, 0))
    for d in range(1, n):
        if d == c or (d ^ c) < d: continue
        for al in range(4):
            for be in range(1, 4):
                f = planes([al if dotm[c][y] else (be if dotm[d][y] else 0) for y in range(n)])
                funcs.setdefault(f, (c, d, al, be))
print("distinct two-level functions:", len(funcs), " (%.0f s)" % (time.time() - t0)); sys.stdout.flush()
q = planes([pc(y) % 4 for y in range(n)])
keys = list(funcs)
negk = [neg(f) for f in keys]
reps = [f for f in keys if funcs[f][0] in (1, 3, 7, 15, 31, 63)]
print("first-flag representatives (top hyperplane c = 1..1 0..0):", len(reps)); sys.stdout.flush()
found = set()
for f1 in reps:
    r = add(q, neg(f1)); rlo, rhi = r
    for i, (nlo, nhi) in enumerate(negk):
        g = (rlo ^ nlo, rhi ^ nhi ^ (rlo & nlo))
        if g in funcs:
            found.add(frozenset([f1, keys[i], g]))
print("solutions with first flag a representative: %d  (%.0f s)" % (len(found), time.time() - t0)); sys.stdout.flush()
# expand by coordinate permutations
def permute_fn(f, p):
    lo = hi = 0
    for y in range(n):
        z = 0
        for b in range(k):
            if y >> b & 1: z |= 1 << p[b]
        if f[0] >> y & 1: lo |= 1 << z
        if f[1] >> y & 1: hi |= 1 << z
    return (lo, hi)
allsol = set()
cache = {}
for p in itertools.permutations(range(k)):
    for s in found:
        t = []
        for f in s:
            key = (f, p)
            if key not in cache: cache[key] = permute_fn(f, p)
            t.append(cache[key])
        allsol.add(frozenset(t))
print("all three-flag identities at 64 points using top two levels only:", len(allsol), "  predicted by the rule: 120"); sys.stdout.flush()
# describe each: sizes, and is it of the predicted kind?
def describe(s):
    out = []
    for f in s:
        c, d, al, be = funcs[f]
        out.append((pc(c), pc(d), pc(c ^ d) if d else 0, al, be))
    return tuple(sorted(out))
from collections import Counter
C = Counter(describe(s) for s in allsol)
print("shapes: (|c|, |d|, |c+d|, alpha, beta) per flag -> how many")
for key, v in sorted(C.items()): print("  ", key, v)
def predicted(s):
    vecs = []
    for f in s:
        c, d, al, be = funcs[f]
        if d == 0 or be != 2 or al not in (1, 3): return False
        d2 = c ^ d
        if not (pc(d) % 4 == al and pc(d2) % 4 == al and pc(d & d2) % 2 == 0): return False
        vecs += [d, d2]
    return all(pc(a & b) % 2 == 0 for a, b in itertools.combinations(vecs, 2))
print("of the predicted kind (orthonormal basis in pairs of equal weight mod 4):", sum(1 for s in allsol if predicted(s)), "of", len(allsol))
exact = 0
for s in allsol:
    ok = True
    for y in range(n):
        tot = 0
        for f in s:
            v = (f[0] >> y & 1) + 2 * (f[1] >> y & 1); tot += v
        if tot != pc(y): ok = False; break
    exact += ok
print("of these, identities that hold for the exact weight with values 0..3 as integers:", exact)
print("total time %.0f s" % (time.time() - t0))
